// La copia de seguridad la genera el servicio 'gymbro-postgres-backup'
// (docker-compose.yml raiz, cada 12 h) en ./postgres/backups, montada
// read-only en /data/pg-backups. Este nodo NO genera backups: selecciona
// el dump mas reciente y reporta los fallidos (dumps de ~0 bytes que deja
// el servicio cuando pg_dump falla).
const fs = require('fs');
const DIR = '/data/pg-backups';
const now = Date.now();
const startedAt = new Date(now).toISOString();

let files = [];
try {
  files = fs.readdirSync(DIR).filter(f => /^smartgymbro_backup_.*\.dump$/.test(f));
} catch (e) {
  return [{ json: { backupFound: false, filename: '', backupPath: '', startedAt, exitCode: 1,
    error: 'No se puede leer ' + DIR + ': ' + String(e.message || e),
    stderr: String(e.message || e), totalDumps: 0, failedDumps: 0 } }];
}

const items = files.map(f => {
  const p = DIR + '/' + f;
  try { const st = fs.statSync(p); return { file: f, path: p, size: st.size, mtimeMs: st.mtimeMs }; }
  catch { return null; }
}).filter(Boolean).sort((a, b) => b.mtimeMs - a.mtimeMs);

const totalDumps = items.length;
const failedDumps = items.filter(i => i.size < 1024).length;

if (items.length === 0) {
  return [{ json: { backupFound: false, filename: '', backupPath: '', startedAt, exitCode: 1,
    error: 'No se encontro ningun smartgymbro_backup_*.dump en ' + DIR,
    stderr: 'directorio vacio o sin dumps', totalDumps, failedDumps } }];
}

const newest = items[0];
return [{
  json: {
    backupFound: true,
    filename: newest.file,
    backupPath: newest.path,
    fileSizeBytes: newest.size,
    fileMtimeMs: newest.mtimeMs,
    ageMinutes: Math.round((now - newest.mtimeMs) / 60000),
    totalDumps,
    failedDumps,
    startedAt,
    exitCode: 0,
    stdout: '',
    stderr: ''
  }
}];

// Verificar el backup generado por el servicio externo:
//  1) el servicio llego a crear al menos un dump
//  2) el mas reciente existe y supera el tamano minimo (los reales pesan ~400 MB;
//     dumps de ~0 bytes indican un pg_dump fallido del servicio)
//  3) su antiguedad no supera 14 h (el servicio corre cada 12 h)
const fs = require('fs');
const params = $input.item.json;
const MAX_AGE_MIN = 14 * 60;
const MIN_SIZE = 10 * 1024 * 1024; // 10 MB

let exists = false, size = 0, mtimeMs = 0, verifyError = '', ageMinutes = null;
if (params.backupFound) {
  try {
    const st = fs.statSync(params.backupPath);
    exists = st.isFile();
    size = st.size;
    mtimeMs = st.mtimeMs;
    ageMinutes = Math.round((Date.now() - mtimeMs) / 60000);
  } catch (e) {
    verifyError = String(e.message || e);
  }
}

const genOk = params.backupFound === true;
const fileOk = exists && size >= MIN_SIZE;
const freshEnough = mtimeMs > 0 && ageMinutes <= MAX_AGE_MIN;
const isValid = genOk && fileOk && freshEnough && !verifyError;

let error = '';
if (!isValid) {
  if (!genOk) error = params.error || 'No se encontro ningun backup en /data/pg-backups';
  else if (verifyError) error = `No se puede leer el archivo: ${verifyError}`;
  else if (size < MIN_SIZE) error = `Backup sospechosamente pequeno (${size} bytes): posible pg_dump fallido del servicio (dumps fallidos detectados: ${params.failedDumps || 0})`;
  else if (!freshEnough) error = `Backup desactualizado: ${ageMinutes} min de antiguedad (maximo ${MAX_AGE_MIN} min). El servicio gymbro-postgres-backup podria estar caido`;
}

return [{
  json: {
    ...params,
    fileExists: exists,
    fileSizeBytes: size,
    fileSizeMB: (size / 1024 / 1024).toFixed(2),
    fileMtime: mtimeMs ? new Date(mtimeMs).toISOString() : '',
    ageMinutes,
    genOk,
    fileOk,
    freshEnough,
    isValid,
    error
  }
}];

// Verificar contenido legible del dump: pg_restore --list (cuenta objetos).
// pg_restore --list solo lee el archivo; NO conecta a la base principal.
// Esta comprobacion exige exitCode 0 y objetos > 0: NO usarlo como sustituto de una restauracion real.
const { execSync } = require('child_process');
const params = $input.item.json;

if (!params.backupPath) {
  return [{ json: { ...params, objectCount: 0, restoreExitCode: 1, restoreError: 'sin archivo de backup', contentOk: false } }];
}

let objectCount = 0, stderr = '', exitCode = 0;
try {
  const out = execSync('pg_restore --list ' + JSON.stringify(params.backupPath), { encoding: 'utf8', shell: '/bin/sh', maxBuffer: 64 * 1024 * 1024 });
  objectCount = out.split('\n').filter(l => l.trim().length > 0).length;
} catch (e) {
  stderr = e.stderr ? e.stderr.toString() : String(e.message || e);
  exitCode = typeof e.status === 'number' ? e.status : 1;
}

const contentOk = exitCode === 0 && objectCount > 0;

return [{ json: { ...params, objectCount, restoreExitCode: exitCode, restoreError: stderr, contentOk } }];

// Backup exitoso: armar el reporte y anexar la linea al log de informes
const fs = require('fs');
const params = $input.item.json;
const stamp = new Date().toISOString();

const report = {
  resultado: 'backup_exitoso',
  filename: params.filename,
  backupPath: params.backupPath,
  fileSizeMB: params.fileSizeMB,
  fileSizeBytes: params.fileSizeBytes,
  ageMinutes: params.ageMinutes,
  objetosEnDump: params.objectCount,
  dumpsEnDirectorio: params.totalDumps,
  dumpsFallidosDetectados: params.failedDumps || 0,
  timestamp: stamp,
  startedAt: params.startedAt
};

console.log('[WF2] Backup verificado exitosamente:', JSON.stringify(report));

const warn = (params.failedDumps || 0) > 0 ? ` | advertencia=${params.failedDumps} dump(s) fallido(s) en /data/pg-backups` : '';
const line = `[${stamp}] resultado=backup_exitoso | archivo=${report.filename} | tamano=${report.fileSizeMB}MB | antiguedad=${report.ageMinutes}min | contenido=OK(objetos=${report.objetosEnDump})${warn} | error=-\n`;
let logWritten = false, logError = '';
try {
  fs.appendFileSync('/data/informes/backup-log.txt', line, 'utf8');
  logWritten = true;
} catch (e) {
  logError = String(e.message || e);
}

return [{ json: { ...report, logWritten, logError } }];

// Backup fallido: armar el reporte y anexar la linea al log de informes
const fs = require('fs');
const params = $input.item.json;
const stamp = new Date().toISOString();

let motivo = params.error || params.restoreError || 'Error desconocido';
if (!motivo && params.exitCode !== 0) motivo = `pg_dump finalizó con código ${params.exitCode}`;
if (!motivo && !params.contentOk) motivo = `pg_restore --list falló o el dump no contiene objetos (exitCode=${params.restoreExitCode}, objetos=${params.objectCount})`;
if (!motivo) motivo = 'Error desconocido';

const report = {
  resultado: 'backup_fallido',
  filename: params.filename,
  backupPath: params.backupPath,
  fileSizeBytes: params.fileSizeBytes || 0,
  ageMinutes: params.ageMinutes,
  error: motivo,
  exitCode: params.exitCode,
  objetosEnDump: params.objectCount || 0,
  dumpsEnDirectorio: params.totalDumps || 0,
  dumpsFallidosDetectados: params.failedDumps || 0,
  timestamp: stamp,
  startedAt: params.startedAt
};

console.error('[WF2] FALLO en backup:', JSON.stringify(report));

const gen = params.genOk ? 'OK' : 'FALLO';
const verif = params.isValid ? 'OK' : 'FALLO';
const contenido = params.contentOk ? `OK(objetos=${params.objectCount})` : `FALLO(exitCode=${params.restoreExitCode}, objetos=${params.objectCount || 0})`;

const line = `[${stamp}] resultado=backup_fallido | archivo=${report.filename || '(ninguno)'} | generacion=${gen} | verificacion_archivo=${verif} | contenido=${contenido} | dumps_fallidos=${report.dumpsFallidosDetectados} | error=${motivo}\n`;
let logWritten = false, logError = '';
try {
  fs.appendFileSync('/data/informes/backup-log.txt', line, 'utf8');
  logWritten = true;
} catch (e) {
  logError = String(e.message || e);
}

return [{ json: { ...report, gen, verif, contenido, logWritten, logError } }];
